[ExtensionOf(classStr(WhsLoadListDP))]
final class AVAWhsLoadListDPCls_Extension
{
}

Method.Source:
/// <summary>
/// Inserts a temporary record to database for a load line.
/// </summary>
/// <param name="_workLine">
/// The work line that represents the load line.
/// </param>
public void insertWHSLoadListTmp(WHSWorkLine   _workLine)
{
    next insertWHSLoadListTmp(_workLine);

    WHSWorkTable avaWHSWorkTable = WHSWorkTable::find(_workLine.WorkId);
    WHSLoadLine avaWhsLoadLine = WHSLoadLine::findbyRecId(_workLine.LoadLineRefRecId);

    whsLoadListTmp.AVALoadListContainerId       = (avaWHSWorkTable.WorkTransType == WHSWorkTransType::Packing) ? avaWHSWorkTable.TargetLicensePlateId : '';
    whsLoadListTmp.AVALoadListProdId            = this.avaGetProdId(avaWHSWorkTable);
    whsLoadListTmp.AVALoadListShippingDate      = whsLoadTable.loadSchedShipDate();
    whsLoadListTmp.AVAInventQtyWork             = _workLine.InventQtyWork;

    whsLoadListTmp.update();
}

/// <summary>
/// returns ProdId from inventTransferOrder or WorkTable OrderNum
/// </summary>
/// <param name = "_workTable">WHSWorkTable</param>
/// <returns>ProdId</returns>
public ProdId avaGetProdId(WHSWorkTable _workTable)
{
    ProdId avaProdId = InventTransferTable::find(_workTable.OrderNum).AVAPOReference;

    if(avaProdId)
    {
        return avaProdId;
    }

    return _workTable.OrderNum;
}
